o=Path(r'C:\tmp\disdex-d126-crossrunner-research-20261126')
src=o/'stable4_p91_offline_entry_parity_20261127.py'
P=o/'STABLE4_P91_ENTRY_PARITY_20261127.json'
assert not P.exists()
def gate(bull,ascore,bscore,bar,prev,signal_ts,asof):
    if not isinstance(bull,bool) or not all(math.isfinite(x) for x in (ascore,bscore,prev)) or prev<=0:return {'gross':0.,'score':None,'pass':False,'reason':'MISSING_INPUT'}
    gross=.5 if bull and ascore>=5 and bscore>=3 else 0. if bull else .75
    if asof<signal_ts+300000 or bar is None or int(bar[0])!=signal_ts:return {'gross':gross,'score':None,'pass':False,'reason':'UNCLOSED_OR_MISSING_M5'}
    op,hi,lo,c,v=map(float,bar[1:6])
    if not all(math.isfinite(x) for x in (op,hi,lo,c,v)) or not (0<lo<=min(op,c)<=max(op,c)<=hi) or v<0:return {'gross':gross,'score':None,'pass':False,'reason':'INVALID_M5'}
    if v<=0:score=None
    else:
        score=int(c<op)+int(c<prev)+int((hi-max(op,c))/max(hi-lo,1e-12)>=.3)
        if c/op>1.004:score-=2
        if c/prev>1.003:score-=1
        if c/prev<.975:score-=1
    return {'gross':gross,'score':score,'pass':gross>0 and score is not None and score>=2,'reason':'MACRO' if gross==0 else 'M5' if score is None or score<2 else 'ELIGIBLE_OFFLINE'}
def raw(p):
    with gzip.open(p,'rt',encoding='utf8') as f:return {int(z[0]):z for l in f if l.strip() for z in [json.loads(l)]}
p75=r/'results/PRISM7_P75_BINANCE_NATIVE62_SAME_UTC_DUAL_POINTS_NO025_TRANSFER_20261122.json'
