m={}
for p in mpaths:
 for t,v in raw(p).items():
  if t in m:assert m[t]==v
  m[t]=v
h=raw(hpath)
old={x['nativeSignalAtUtcH1Close']:x for l in p91.read_text().splitlines() for x in [json.loads(l)]}
accepted={x['sourceNativeEntryHourTs'] for l in pacc.read_text().splitlines() for x in [json.loads(l)]}
