rows=[];bad=[];early=0
for x in xs:
 t=x['entryTs']
 if t not in old:continue
 z=x['dualSigned'];args=(z['macroBullBothBTCAndEthereum'],z['asterPENGUSignedPoints'],z['binancePENGUSignedPoints'],m[t],float(h[t-3600000][4]),t)
 q=gate(*args,t+300000);v=old[t]
 exp=(v['ownerP73GrossBeforeM5'],v['asterClosedM5Check']['score'],t in accepted)
 got=(q['gross'],q['score'],q['pass'])
 if got!=exp:bad.append((t,exp,got))
 assert not gate(*args,t+299999)['pass'];early+=1
 assert not gate(*args[:3],None,*args[4:],t+300000)['pass']
 rows.append({'ts':t,'expected':exp,'actual':got})
assert len(rows)==41
# Validate the saved R26 single-slot modeled fills independently from decision engine.
out={}
for fee in (10,30):
 p=b/'STABLE4_R26_CAPITAL_ALLOCATION_V3_RESEARCH_20261127'/f'R21_ONE_{fee}BPS_FILLS.csv'
 with p.open(encoding='utf-8-sig') as f:a=[x for x in csv.DictReader(f) if x['route'].startswith('R21_')]
 a.sort(key=lambda x:x['entry_utc']);cool={};prev_end=None;viol=[]
 def dt(s):return datetime.datetime.fromisoformat(s.replace('Z','+00:00'))
 for x in a:
  t,e=dt(x['entry_utc']),dt(x['exit_utc']);s=x['symbol']
  if prev_end and t<prev_end:viol.append((x['source_signal_id'],'OVERLAP'))
  if s in cool and t<cool[s]:viol.append((x['source_signal_id'],'COOLDOWN'))
  if abs(float(x['gross_x'])-.3)>1e-9:viol.append((x['source_signal_id'],'GROSS'))
  if x['side']!='SHORT':viol.append((x['source_signal_id'],'SIDE'))
  lim=24 if x['route']=='R21_OLD24' else 48 if x['route']=='R21_NEW48' else 0
  if not 0<(e-t).total_seconds()<=lim*3600:viol.append((x['source_signal_id'],'HORIZON'))
  prev_end=e;cool[s]=e+datetime.timedelta(hours=12)
 out[str(fee)]={'count':len(a),'violations':viol,'ledger_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'exit_reasons':dict(collections.Counter(x['exit_model_reason'] for x in a))}
d={'status':'OFFLINE_ONLY_NO_LIVE','pengu_gate':{'rows':len(rows),'mismatches':bad,'accepted':sum(x['actual'][2] for x in rows),'early_and_missing_rejected':early,'details':rows},'r21_single_slot':out,'inputs_sha256':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in [p75,p91,pacc,hpath,*mpaths]},'limitations':'P75 Binance native trigger and macro features are frozen inputs; not independently regenerated. R26 completed fill audit only, no runtime pending or exchange certification. No order permissions.'}
